    15→
    16→import java.util.ArrayList;
    17→import java.util.List;
    18→import org.apache.tuweni.bytes.Bytes;
    19→import tech.pegasys.teku.spec.datastructures.execution.ExecutionRequestsBuilder;
    20→
    21→/*
    22→ Implement the rules for decoding and hashing execution requests according to https://eips.ethereum.org/EIPS/eip-7685
    23→*/
    24→public class ExecutionRequestsDataCodec {
    25→
    26→  private final ExecutionRequestsSchema executionRequestsSchema;
    27→
    28→  public ExecutionRequestsDataCodec(final ExecutionRequestsSchema executionRequestsSchema) {
    29→    this.executionRequestsSchema = executionRequestsSchema;
    30→  }
    31→
    32→  /**
    33→   * Decodes the execution requests received from the EL.
    34→   *
    35→   * @param executionRequests list of encoded execution requests from the EL
    36→   * @return an ExecutionRequests object with the requests
    37→   */
    38→  public ExecutionRequests decode(final List<Bytes> executionRequests) {
    39→    final ExecutionRequestsBuilder executionRequestsBuilder =
    40→        new ExecutionRequestsBuilderElectra(executionRequestsSchema);
    41→
    42→    byte previousRequestType = -1;
    43→    for (final Bytes request : executionRequests) {
    44→      if (request.isEmpty()) {
    45→        throw new IllegalArgumentException("Execution request data must not be empty");
    46→      }
    47→
    48→      final byte requestType = request.get(0);
    49→      if (requestType <= previousRequestType) {
    50→        throw new IllegalArgumentException(
    51→            "Execution requests are not in strictly ascending order");
    52→      }
    53→
    54→      final Bytes requestData = request.slice(1);
    55→      if (requestData.isEmpty()) {
    56→        throw new IllegalArgumentException("Empty data for request type " + requestType);
    57→      }
    58→
    59→      switch (requestType) {
    60→        case DepositRequest.REQUEST_TYPE ->
    61→            executionRequestsBuilder.deposits(
    62→                executionRequestsSchema
    63→                    .getDepositRequestsSchema()
    64→                    .sszDeserialize(requestData)
    65→                    .asList());
    66→        case WithdrawalRequest.REQUEST_TYPE ->
    67→            executionRequestsBuilder.withdrawals(
    68→                executionRequestsSchema
    69→                    .getWithdrawalRequestsSchema()
    70→                    .sszDeserialize(requestData)
    71→                    .asList());
    72→        case ConsolidationRequest.REQUEST_TYPE ->
    73→            executionRequestsBuilder.consolidations(
    74→                executionRequestsSchema
    75→                    .getConsolidationRequestsSchema()
    76→                    .sszDeserialize(requestData)
    77→                    .asList());
    78→        default ->
    79→            throw new IllegalArgumentException("Invalid execution request type: " + requestType);
    80→      }
    81→      previousRequestType = requestType;
    82→    }
    83→
    84→    return executionRequestsBuilder.build();
    85→  }
    86→
    87→  /**
    88→   * Encodes the provided ExecutionRequests object to send the requests to the EL for validation.
    89→   *
    90→   * @param executionRequests the execution requests in the BeaconBlock
    91→   * @return list of encoded execution requests
    92→   */
    93→  public List<Bytes> encode(final ExecutionRequests executionRequests) {
    94→    final List<Bytes> executionRequestsData = new ArrayList<>();
    95→    final List<DepositRequest> deposits = executionRequests.getDeposits();
    96→    if (!deposits.isEmpty()) {
    97→      final Bytes depositRequestsData =
    98→          executionRequestsSchema
    99→              .getDepositRequestsSchema()
   100→              .createFromElements(deposits)
   101→              .sszSerialize();
   102→      executionRequestsData.add(
   103→          Bytes.concatenate(DepositRequest.REQUEST_TYPE_PREFIX, depositRequestsData));
   104→    }
   105→    final List<WithdrawalRequest> withdrawals = executionRequests.getWithdrawals();
   106→    if (!withdrawals.isEmpty()) {
   107→      final Bytes withdrawalsRequestsData =
   108→          executionRequestsSchema
   109→              .getWithdrawalRequestsSchema()
   110→              .createFromElements(withdrawals)
   111→              .sszSerialize();
   112→      executionRequestsData.add(
   113→          Bytes.concatenate(WithdrawalRequest.REQUEST_TYPE_PREFIX, withdrawalsRequestsData));
   114→    }
   115→    final List<ConsolidationRequest> consolidations = executionRequests.getConsolidations();
   116→    if (!consolidations.isEmpty()) {
   117→      final Bytes consolidationRequestsData =
   118→          executionRequestsSchema
   119→              .getConsolidationRequestsSchema()
   120→              .createFromElements(consolidations)
   121→              .sszSerialize();
   122→      executionRequestsData.add(
   123→          Bytes.concatenate(ConsolidationRequest.REQUEST_TYPE_PREFIX, consolidationRequestsData));
   124→    }
   125→    return executionRequestsData;
   126→  }
   127→}
