   402→  @Override
   403→  public void processConsolidationRequests(
   404→      final MutableBeaconState state, final List<ConsolidationRequest> consolidationRequests) {
   405→    LOG.debug(
   406→        "process_consolidation_request: {} consolidation requests to process from block at "
   407→            + "slot {}",
   408→        consolidationRequests.size(),
   409→        state.getSlot());
   410→
   411→    final MutableBeaconStateElectra electraState = MutableBeaconStateElectra.required(state);
   412→    consolidationRequests.forEach(
   413→        consolidationRequest -> processConsolidationRequest(electraState, consolidationRequest));
   414→  }
   415→
   416→  private void processConsolidationRequest(
   417→      final MutableBeaconStateElectra state, final ConsolidationRequest consolidationRequest) {
   418→    final UInt64 slot = state.getSlot();
   419→    final UInt64 currentEpoch = miscHelpers.computeEpochAtSlot(slot);
   420→
   421→    if (isValidSwitchToCompoundingRequest(state, consolidationRequest)) {
   422→      LOG.debug(
   423→          "process_consolidation_request: switching validator {} to compounding address",
   424→          consolidationRequest.getSourcePubkey().toAbbreviatedString());
   425→      validatorsUtil
   426→          .getValidatorIndex(state, consolidationRequest.getSourcePubkey())
   427→          .ifPresent(
   428→              sourceValidatorIndex ->
   429→                  beaconStateMutatorsElectra.switchToCompoundingValidator(
   430→                      state, sourceValidatorIndex));
   431→      return;
   432→    }
   433→
   434→    // Verify that source != target, so a consolidation cannot be used as an exit
   435→    if (consolidationRequest.getSourcePubkey().equals(consolidationRequest.getTargetPubkey())) {
   436→      LOG.debug(
   437→          "process_consolidation_request: source_pubkey and target_pubkey must be different (pubkey = {})",
   438→          consolidationRequest.getSourcePubkey().toAbbreviatedString());
   439→      return;
   440→    }
   441→
   442→    // If the pending consolidations queue is full, consolidation requests are ignored
   443→    if (state.getPendingConsolidations().size()
   444→        == specConfigElectra.getPendingConsolidationsLimit()) {
   445→      LOG.debug("process_consolidation_request: consolidation queue is full");
   446→      return;
   447→    }
   448→
   449→    // If there is too little available consolidation churn limit, consolidation requests are
   450→    // ignored
   451→    if (beaconStateAccessorsElectra
   452→        .getConsolidationChurnLimit(state)
   453→        .isLessThanOrEqualTo(specConfigElectra.getMinActivationBalance())) {
   454→      LOG.debug("process_consolidation_request: not enough consolidation churn limit available");
   455→      return;
   456→    }
   457→
   458→    // Verify source_pubkey exists
   459→    final Optional<Integer> maybeSourceValidatorIndex =
   460→        validatorsUtil.getValidatorIndex(state, consolidationRequest.getSourcePubkey());
   461→    if (maybeSourceValidatorIndex.isEmpty()) {
