   130→  @Override
   131→  public NewPayloadRequest computeNewPayloadRequest(
   132→      final BeaconState state, final BeaconBlockBody beaconBlockBody)
   133→      throws BlockProcessingException {
   134→    final ExecutionPayload executionPayload = extractExecutionPayload(beaconBlockBody);
   135→    final SszList<SszKZGCommitment> blobKzgCommitments = extractBlobKzgCommitments(beaconBlockBody);
   136→    final List<VersionedHash> versionedHashes =
   137→        blobKzgCommitments.stream()
   138→            .map(SszKZGCommitment::getKZGCommitment)
   139→            .map(miscHelpers::kzgCommitmentToVersionedHash)
   140→            .toList();
   141→    final Bytes32 parentBeaconBlockRoot = state.getLatestBlockHeader().getParentRoot();
   142→    final ExecutionRequests executionRequests =
   143→        beaconBlockBody
   144→            .getOptionalExecutionRequests()
   145→            .orElseThrow(() -> new BlockProcessingException("Execution requests expected"));
   146→    return new NewPayloadRequest(
   147→        executionPayload,
   148→        versionedHashes,
   149→        parentBeaconBlockRoot,
   150→        executionRequestsDataCodec.encode(executionRequests));
   151→  }
