   153→  @Override
   154→  protected void processOperationsNoValidation(
   155→      final MutableBeaconState state,
   156→      final BeaconBlockBody body,
   157→      final IndexedAttestationCache indexedAttestationCache,
   158→      final Supplier<ValidatorExitContext> validatorExitContextSupplier)
   159→      throws BlockProcessingException {
   160→    super.processOperationsNoValidation(
   161→        state, body, indexedAttestationCache, validatorExitContextSupplier);
   162→
   163→    safelyProcess(
   164→        () -> {
   165→          final ExecutionRequests executionRequests =
   166→              body.getOptionalExecutionRequests()
   167→                  .orElseThrow(() -> new BlockProcessingException("Execution requests expected"));
   168→
   169→          processDepositRequests(state, executionRequests.getDeposits());
   170→          processWithdrawalRequests(
   171→              state, executionRequests.getWithdrawals(), validatorExitContextSupplier);
   172→          processConsolidationRequests(state, executionRequests.getConsolidations());
   173→        });
   174→  }
