   176→  @Override
   177→  protected void verifyOutstandingDepositsAreProcessed(
   178→      final BeaconState state, final BeaconBlockBody body) {
   179→    final UInt64 eth1DepositIndexLimit =
   180→        state
   181→            .getEth1Data()
   182→            .getDepositCount()
   183→            .min(BeaconStateElectra.required(state).getDepositRequestsStartIndex());
   184→
   185→    if (state.getEth1DepositIndex().isLessThan(eth1DepositIndexLimit)) {
   186→      final int expectedDepositCount =
   187→          Math.min(
   188→              specConfig.getMaxDeposits(),
   189→              eth1DepositIndexLimit.minusMinZero(state.getEth1DepositIndex()).intValue());
   190→
   191→      checkArgument(
   192→          body.getDeposits().size() == expectedDepositCount,
   193→          "process_operations: Verify that outstanding deposits are processed up to the maximum number of deposits");
   194→    } else {
   195→      checkArgument(
   196→          body.getDeposits().isEmpty(),
   197→          "process_operations: Verify that former deposit mechanism has been disabled");
   198→    }
   199→  }
