   215→  /*
   216→   Implements process_deposit_request from consensus-specs (EIP-6110)
   217→  */
   218→  @Override
   219→  public void processDepositRequests(
   220→      final MutableBeaconState state, final List<DepositRequest> depositRequests) {
   221→    final MutableBeaconStateElectra electraState = MutableBeaconStateElectra.required(state);
   222→    final SszMutableList<PendingDeposit> pendingDeposits =
   223→        MutableBeaconStateElectra.required(state).getPendingDeposits();
   224→    for (DepositRequest depositRequest : depositRequests) {
   225→      // process_deposit_request
   226→      if (electraState
   227→          .getDepositRequestsStartIndex()
   228→          .equals(SpecConfigElectra.UNSET_DEPOSIT_REQUESTS_START_INDEX)) {
   229→        electraState.setDepositRequestsStartIndex(depositRequest.getIndex());
   230→      }
   231→
   232→      final PendingDeposit deposit =
   233→          schemaDefinitionsElectra
   234→              .getPendingDepositSchema()
   235→              .create(
   236→                  new SszPublicKey(depositRequest.getPubkey()),
   237→                  SszBytes32.of(depositRequest.getWithdrawalCredentials()),
   238→                  SszUInt64.of(depositRequest.getAmount()),
   239→                  new SszSignature(depositRequest.getSignature()),
   240→                  SszUInt64.of(state.getSlot()));
   241→      pendingDeposits.append(deposit);
   242→    }
   243→  }
