   245→  /** Implements process_withdrawal_request from consensus-specs (EIP-7002 & EIP-7251). */
   246→  @Override
   247→  public void processWithdrawalRequests(
   248→      final MutableBeaconState state,
   249→      final List<WithdrawalRequest> withdrawalRequests,
   250→      final Supplier<ValidatorExitContext> validatorExitContextSupplier) {
   251→    final UInt64 slot = state.getSlot();
   252→    final UInt64 currentEpoch = miscHelpers.computeEpochAtSlot(slot);
   253→
   254→    LOG.debug(
   255→        "process_withdrawal_request: {} withdrawal request to process from block at " + "slot {}",
   256→        withdrawalRequests.size(),
   257→        slot);
   258→
   259→    withdrawalRequests.forEach(
   260→        withdrawalRequest -> {
   261→          LOG.debug(
   262→              "process_withdrawal_request: processing withdrawal request {}", withdrawalRequest);
   263→
   264→          // If partial withdrawal queue is full, only full exits are processed
   265→          final boolean isFullExitRequest =
   266→              withdrawalRequest.getAmount().equals(FULL_EXIT_REQUEST_AMOUNT);
   267→          final boolean partialWithdrawalsQueueFull =
   268→              state.toVersionElectra().orElseThrow().getPendingPartialWithdrawals().size()
   269→                  == specConfigElectra.getPendingPartialWithdrawalsLimit();
   270→          if (partialWithdrawalsQueueFull && !isFullExitRequest) {
   271→            LOG.debug("process_withdrawal_request: partial withdrawal queue is full");
   272→            return;
   273→          }
   274→
   275→          final Optional<Integer> maybeValidatorIndex =
   276→              validatorsUtil.getValidatorIndex(state, withdrawalRequest.getValidatorPubkey());
   277→          if (maybeValidatorIndex.isEmpty()) {
   278→            LOG.debug(
   279→                "process_withdrawal_request: no matching validator for public key {}",
   280→                withdrawalRequest.getValidatorPubkey().toAbbreviatedString());
   281→            return;
   282→          }
   283→
   284→          final int validatorIndex = maybeValidatorIndex.get();
   285→          final Validator validator = state.getValidators().get(validatorIndex);
   286→
   287→          // Check if validator has an execution address set
   288→          final boolean hasExecutionAddress =
   289→              predicatesElectra.hasExecutionWithdrawalCredential(validator);
   290→          if (!hasExecutionAddress) {
   291→            LOG.debug(
   292→                "process_withdrawal_request: validator index {} does not have withdrawal credentials set",
   293→                validatorIndex);
   294→            return;
   295→          }
   296→
   297→          // Check withdrawalRequest source_address matches validator eth1 withdrawal credentials
   298→          final Bytes20 validatorExecutionAddress =
   299→              new Bytes20(validator.getWithdrawalCredentials().slice(12));
   300→          final Bytes20 withdrawalRequestSourceAddress = withdrawalRequest.getSourceAddress();
   301→          final boolean isCorrectSourceAddress =
   302→              validatorExecutionAddress.equals(withdrawalRequestSourceAddress);
   303→          if (!isCorrectSourceAddress) {
   304→            LOG.debug(
   305→                "process_withdrawal_request: WithdrawalRequest source_address {} does not match "
   306→                    + "validator {} withdrawal credentials {}",
   307→                withdrawalRequestSourceAddress,
   308→                validatorIndex,
   309→                validatorExecutionAddress);
   310→            return;
   311→          }
   312→
   313→          // Check if validator is active
   314→          final boolean isValidatorActive = predicates.isActiveValidator(validator, currentEpoch);
   315→          if (!isValidatorActive) {
   316→            LOG.debug("process_withdrawal_request: Validator {} is not active", validatorIndex);
   317→            return;
   318→          }
   319→
   320→          // Check if validator has already initiated exit
   321→          final boolean hasInitiatedExit = !validator.getExitEpoch().equals(FAR_FUTURE_EPOCH);
   322→          if (hasInitiatedExit) {
   323→            LOG.debug(
   324→                "process_withdrawal_request: Validator {} has already initiated exit",
   325→                validatorIndex);
   326→            return;
   327→          }
   328→
   329→          // Check if validator has been active long enough
   330→          final boolean validatorActiveLongEnough =
   331→              currentEpoch.isGreaterThanOrEqualTo(
   332→                  validator.getActivationEpoch().plus(specConfig.getShardCommitteePeriod()));
   333→          if (!validatorActiveLongEnough) {
   334→            LOG.debug(
   335→                "process_withdrawal_request: Validator {} is not active long enough",
   336→                validatorIndex);
   337→            return;
   338→          }
   339→
   340→          final UInt64 pendingBalanceToWithdraw =
   341→              validatorsUtil.getPendingBalanceToWithdraw(state, validatorIndex);
   342→          if (isFullExitRequest) {
   343→            // Only exit validator if it has no pending withdrawals in the queue
   344→            if (pendingBalanceToWithdraw.isZero()) {
   345→              LOG.debug(
   346→                  "process_withdrawal_request: Initiating exit for validator {}", validatorIndex);
   347→
   348→              beaconStateMutators.initiateValidatorExit(
   349→                  state, validatorIndex, validatorExitContextSupplier);
   350→            }
   351→            return;
   352→          }
   353→
   354→          final UInt64 validatorBalance = state.getBalances().get(validatorIndex).get();
   355→          final UInt64 minActivationBalance = specConfigElectra.getMinActivationBalance();
   356→
   357→          final boolean hasCompoundingWithdrawalCredential =
   358→              predicatesElectra.hasCompoundingWithdrawalCredential(validator);
   359→          final boolean hasSufficientEffectiveBalance =
   360→              validator.getEffectiveBalance().isGreaterThanOrEqualTo(minActivationBalance);
   361→          final boolean hasExcessBalance =
   362→              validatorBalance.isGreaterThan(minActivationBalance.plus(pendingBalanceToWithdraw));
   363→          if (hasCompoundingWithdrawalCredential
   364→              && hasSufficientEffectiveBalance
   365→              && hasExcessBalance) {
   366→            final UInt64 toWithdraw =
   367→                validatorBalance
   368→                    .minusMinZero(minActivationBalance)
   369→                    .minusMinZero(pendingBalanceToWithdraw)
   370→                    .min(withdrawalRequest.getAmount());
   371→            final MutableBeaconStateElectra electraState =
   372→                MutableBeaconStateElectra.required(state);
   373→            final UInt64 exitQueueEpoch =
   374→                beaconStateMutatorsElectra.computeExitEpochAndUpdateChurn(electraState, toWithdraw);
   375→            final UInt64 withdrawableEpoch =
   376→                exitQueueEpoch.plus(specConfigElectra.getMinValidatorWithdrawabilityDelay());
   377→
   378→            LOG.debug(
   379→                "process_withdrawal_request: Creating pending partial withdrawal for validator {}",
   380→                validatorIndex);
   381→
   382→            electraState
   383→                .getPendingPartialWithdrawals()
   384→                .append(
   385→                    schemaDefinitionsElectra
   386→                        .getPendingPartialWithdrawalSchema()
   387→                        .create(
   388→                            SszUInt64.of(UInt64.fromLongBits(validatorIndex)),
   389→                            SszUInt64.of(toWithdraw),
   390→                            SszUInt64.of(withdrawableEpoch)));
   391→          }
   392→        });
   393→  }
   394→
   395→  /**
   396→   * Implements process_consolidation_request from consensus-spec (EIP-7251)
   397→   *
   398→   * @see <a
   399→   *     href="https://github.com/ethereum/consensus-specs/blob/master/specs/electra/beacon-chain
   400→   *     .md#new-process_consolidation_request"/>
   401→   */
   402→  @Override
   403→  public void processConsolidationRequests(
   404→      final MutableBeaconState state, final List<ConsolidationRequest> consolidationRequests) {
   405→    LOG.debug(
   406→        "process_consolidation_request: {} consolidation requests to process from block at "
   407→            + "slot {}",
   408→        consolidationRequests.size(),
   409→        state.getSlot());
   410→
   411→    final MutableBeaconStateElectra electraState = MutableBeaconStateElectra.required(state);
   412→    consolidationRequests.forEach(
   413→        consolidationRequest -> processConsolidationRequest(electraState, consolidationRequest));
   414→  }
   415→
   416→  private void processConsolidationRequest(
   417→      final MutableBeaconStateElectra state, final ConsolidationRequest consolidationRequest) {
   418→    final UInt64 slot = state.getSlot();
   419→    final UInt64 currentEpoch = miscHelpers.computeEpochAtSlot(slot);
   420→
   421→    if (isValidSwitchToCompoundingRequest(state, consolidationRequest)) {
   422→      LOG.debug(
   423→          "process_consolidation_request: switching validator {} to compounding address",
   424→          consolidationRequest.getSourcePubkey().toAbbreviatedString());
   425→      validatorsUtil
   426→          .getValidatorIndex(state, consolidationRequest.getSourcePubkey())
   427→          .ifPresent(
   428→              sourceValidatorIndex ->
   429→                  beaconStateMutatorsElectra.switchToCompoundingValidator(
   430→                      state, sourceValidatorIndex));
   431→      return;
   432→    }
   433→
   434→    // Verify that source != target, so a consolidation cannot be used as an exit
   435→    if (consolidationRequest.getSourcePubkey().equals(consolidationRequest.getTargetPubkey())) {
   436→      LOG.debug(
   437→          "process_consolidation_request: source_pubkey and target_pubkey must be different (pubkey = {})",
   438→          consolidationRequest.getSourcePubkey().toAbbreviatedString());
   439→      return;
   440→    }
   441→
   442→    // If the pending consolidations queue is full, consolidation requests are ignored
   443→    if (state.getPendingConsolidations().size()
   444→        == specConfigElectra.getPendingConsolidationsLimit()) {
   445→      LOG.debug("process_consolidation_request: consolidation queue is full");
   446→      return;
   447→    }
   448→
   449→    // If there is too little available consolidation churn limit, consolidation requests are
   450→    // ignored
   451→    if (beaconStateAccessorsElectra
   452→        .getConsolidationChurnLimit(state)
   453→        .isLessThanOrEqualTo(specConfigElectra.getMinActivationBalance())) {
   454→      LOG.debug("process_consolidation_request: not enough consolidation churn limit available");
   455→      return;
   456→    }
   457→
   458→    // Verify source_pubkey exists
   459→    final Optional<Integer> maybeSourceValidatorIndex =
   460→        validatorsUtil.getValidatorIndex(state, consolidationRequest.getSourcePubkey());
   461→    if (maybeSourceValidatorIndex.isEmpty()) {
   462→      LOG.debug(
   463→          "process_consolidation_request: source_pubkey {} not found",
   464→          consolidationRequest.getSourcePubkey().toAbbreviatedString());
   465→      return;
   466→    }
   467→
   468→    // Verify target_pubkey exists
   469→    final Optional<Integer> maybeTargetValidatorIndex =
   470→        validatorsUtil.getValidatorIndex(state, consolidationRequest.getTargetPubkey());
   471→    if (maybeTargetValidatorIndex.isEmpty()) {
   472→      LOG.debug(
   473→          "process_consolidation_request: target_pubkey {} not found",
   474→          consolidationRequest.getTargetPubkey().toAbbreviatedString());
   475→      return;
   476→    }
   477→
   478→    final int sourceValidatorIndex = maybeSourceValidatorIndex.get();
   479→    final Validator sourceValidator = state.getValidators().get(sourceValidatorIndex);
   480→    final int targetValidatorIndex = maybeTargetValidatorIndex.get();
   481→    final Validator targetValidator = state.getValidators().get(targetValidatorIndex);
   482→
   483→    // Verify source withdrawal credentials
   484→    final boolean sourceHasExecutionWithdrawalCredentials =
   485→        predicatesElectra.hasExecutionWithdrawalCredential(sourceValidator);
   486→
   487→    final Eth1Address sourceValidatorExecutionAddress =
   488→        Predicates.getExecutionAddressUnchecked(sourceValidator.getWithdrawalCredentials());
   489→    final boolean sourceHasCorrectCredentials =
   490→        sourceValidatorExecutionAddress.equals(
   491→            Eth1Address.fromBytes(consolidationRequest.getSourceAddress().getWrappedBytes()));
   492→    if (!(sourceHasExecutionWithdrawalCredentials && sourceHasCorrectCredentials)) {
   493→      LOG.debug("process_consolidation_request: invalid source credentials");
   494→      return;
   495→    }
   496→
   497→    // Verify that target has compounding withdrawal credentials
   498→    if (!predicatesElectra.hasCompoundingWithdrawalCredential(targetValidator)) {
   499→      LOG.debug("process_consolidation_request: invalid target credentials");
   500→      return;
   501→    }
   502→
   503→    // Verify the source and the target are active
   504→    if (!predicatesElectra.isActiveValidator(sourceValidator, currentEpoch)) {
   505→      LOG.debug(
   506→          "process_consolidation_request: source validator {} is inactive", sourceValidatorIndex);
   507→      return;
   508→    }
   509→    if (!predicatesElectra.isActiveValidator(targetValidator, currentEpoch)) {
   510→      LOG.debug(
   511→          "process_consolidation_request: target validator {} is inactive", targetValidatorIndex);
   512→      return;
   513→    }
   514→
   515→    // Verify exits for source and target have not been initiated
   516→    if (!sourceValidator.getExitEpoch().equals(FAR_FUTURE_EPOCH)) {
   517→      LOG.debug(
   518→          "process_consolidation_request: source validator {} is exiting", sourceValidatorIndex);
   519→      return;
   520→    }
   521→    if (!targetValidator.getExitEpoch().equals(FAR_FUTURE_EPOCH)) {
   522→      LOG.debug(
   523→          "process_consolidation_request: target validator {} is exiting", targetValidatorIndex);
   524→      return;
   525→    }
   526→
   527→    // Verify the source has been active long enough
   528→    if (currentEpoch.isLessThan(
   529→        sourceValidator.getActivationEpoch().plus(specConfig.getShardCommitteePeriod()))) {
   530→      LOG.debug("process_consolidation_request: source has not been active long enough");
   531→      return;
   532→    }
   533→    // Verify the source has no pending withdrawals in the queue
   534→    if (beaconStateAccessorsElectra
   535→        .getPendingBalanceToWithdraw(state, sourceValidatorIndex)
   536→        .isGreaterThan(ZERO)) {
   537→      LOG.debug("process_consolidation_request: source has pending withdrawals in the queue");
   538→      return;
   539→    }
   540→
   541→    // Initiate source validator exit and append pending consolidation
   542→    final UInt64 exitEpoch =
   543→        beaconStateMutatorsElectra.computeConsolidationEpochAndUpdateChurn(
   544→            state, sourceValidator.getEffectiveBalance());
   545→    final UInt64 withdrawableEpoch =
   546→        exitEpoch.plus(specConfigElectra.getMinValidatorWithdrawabilityDelay());
   547→
   548→    state
   549→        .getValidators()
   550→        .update(
   551→            sourceValidatorIndex,
   552→            v -> v.withExitEpoch(exitEpoch).withWithdrawableEpoch(withdrawableEpoch));
   553→    LOG.debug(
   554→        "process_consolidation_request: updated validator {} with exit_epoch = {}, withdrawable_epoch = {}",
   555→        sourceValidatorIndex,
   556→        exitEpoch,
   557→        withdrawableEpoch);
   558→
   559→    final PendingConsolidation pendingConsolidation =
   560→        new PendingConsolidation(
   561→            schemaDefinitionsElectra.getPendingConsolidationSchema(),
   562→            SszUInt64.of(UInt64.valueOf(sourceValidatorIndex)),
   563→            SszUInt64.of(UInt64.valueOf(targetValidatorIndex)));
   564→    state.getPendingConsolidations().append(pendingConsolidation);
   565→
   566→    LOG.debug("process_consolidation_request: created {}", pendingConsolidation);
   567→  }
   568→
   569→  /**
   570→   * Implements function is_valid_switch_to_compounding_request
   571→   *
   572→   * @see <a
   573→   *     href="https://github.com/ethereum/consensus-specs/blob/master/specs/electra/beacon-chain.md#new-is_valid_switch_to_compounding_request"/>
   574→   */
   575→  @Override
   576→  public boolean isValidSwitchToCompoundingRequest(
   577→      final BeaconState state, final ConsolidationRequest consolidationRequest) {
   578→
   579→    // Switch to compounding requires source and target be equal
   580→    if (!consolidationRequest.getSourcePubkey().equals(consolidationRequest.getTargetPubkey())) {
   581→      return false;
   582→    }
   583→
   584→    // Verify source_pubkey exists
   585→    final Optional<Integer> maybeSourceValidatorIndex =
   586→        validatorsUtil.getValidatorIndex(state, consolidationRequest.getSourcePubkey());
   587→    if (maybeSourceValidatorIndex.isEmpty()) {
   588→      return false;
   589→    }
   590→
   591→    final int sourceValidatorIndex = maybeSourceValidatorIndex.get();
   592→    final Validator sourceValidator = state.getValidators().get(sourceValidatorIndex);
   593→
   594→    // Verify request has been authorized
   595→    final Eth1Address sourceValidatorExecutionAddress =
   596→        Predicates.getExecutionAddressUnchecked(sourceValidator.getWithdrawalCredentials());
   597→    if (!sourceValidatorExecutionAddress.equals(
   598→        Eth1Address.fromBytes(consolidationRequest.getSourceAddress().getWrappedBytes()))) {
   599→      return false;
   600→    }
   601→
   602→    // Verify source withdrawal credentials
   603→    if (!predicatesElectra.hasEth1WithdrawalCredential(sourceValidator)) {
   604→      return false;
   605→    }
   606→
   607→    // Verify the source is active
   608→    final UInt64 currentEpoch = miscHelpers.computeEpochAtSlot(state.getSlot());
   609→    if (!predicatesElectra.isActiveValidator(sourceValidator, currentEpoch)) {
   610→      return false;
   611→    }
   612→
   613→    // Verify exit for source has not been initiated
   614→    return sourceValidator.getExitEpoch().equals(FAR_FUTURE_EPOCH);
   615→  }
   616→
   617→  @Override
   618→  public void applyDeposit(
   619→      final MutableBeaconState state,
   620→      final BLSPublicKey pubkey,
   621→      final Bytes32 withdrawalCredentials,
   622→      final UInt64 amount,
   623→      final BLSSignature signature,
   624→      final Optional<Object2IntMap<BLSPublicKey>> maybePubkeyToIndexMap,
   625→      final boolean signatureAlreadyVerified) {
   626→
   627→    // Find the validator index associated with this deposit, if it exists
   628→    final Optional<Integer> existingIndex =
   629→        maybePubkeyToIndexMap
   630→            .flatMap(
   631→                pubkeyToIndexMap -> {
   632→                  if (pubkeyToIndexMap.containsKey(pubkey)) {
   633→                    return Optional.of(pubkeyToIndexMap.getInt(pubkey));
   634→                  } else {
   635→                    pubkeyToIndexMap.put(pubkey, state.getValidators().size());
   636→                    return Optional.empty();
   637→                  }
   638→                })
   639→            .or(() -> validatorsUtil.getValidatorIndex(state, pubkey));
   640→
   641→    if (existingIndex.isEmpty()) {
   642→      // This is a new validator
   643→      // Verify the deposit signature (proof of possession) which is not checked by the deposit
   644→      // contract
   645→      if (signatureAlreadyVerified
   646→          || miscHelpers.isValidDepositSignature(
   647→              pubkey, withdrawalCredentials, amount, signature)) {
   648→        beaconStateMutators.addValidatorToRegistry(state, pubkey, withdrawalCredentials, ZERO);
   649→        final PendingDeposit deposit =
   650→            schemaDefinitionsElectra
   651→                .getPendingDepositSchema()
   652→                .create(
   653→                    new SszPublicKey(pubkey),
   654→                    SszBytes32.of(withdrawalCredentials),
   655→                    SszUInt64.of(amount),
   656→                    new SszSignature(signature),
   657→                    SszUInt64.of(SpecConfig.GENESIS_SLOT));
   658→        MutableBeaconStateElectra.required(state).getPendingDeposits().append(deposit);
   659→      } else {
   660→        handleInvalidDeposit(pubkey, maybePubkeyToIndexMap);
   661→      }
   662→    } else {
   663→      final PendingDeposit deposit =
   664→          schemaDefinitionsElectra
   665→              .getPendingDepositSchema()
   666→              .create(
   667→                  new SszPublicKey(pubkey),
   668→                  SszBytes32.of(withdrawalCredentials),
   669→                  SszUInt64.of(amount),
   670→                  new SszSignature(signature),
   671→                  SszUInt64.of(SpecConfig.GENESIS_SLOT));
   672→      MutableBeaconStateElectra.required(state).getPendingDeposits().append(deposit);
   673→    }
   674→  }
   675→
   676→  @Override
   677→  public void processDepositWithoutCheckingMerkleProof(
   678→      final MutableBeaconState state,
   679→      final Deposit deposit,
   680→      final Optional<Object2IntMap<BLSPublicKey>> maybePubkeyToIndexMap,
   681→      final boolean signatureAlreadyVerified) {
   682→    state.setEth1DepositIndex(state.getEth1DepositIndex().plus(UInt64.ONE));
   683→
   684→    applyDeposit(
   685→        state,
   686→        deposit.getData().getPubkey(),
   687→        deposit.getData().getWithdrawalCredentials(),
   688→        deposit.getData().getAmount(),
   689→        deposit.getData().getSignature(),
   690→        maybePubkeyToIndexMap,
   691→        signatureAlreadyVerified);
   692→  }
   693→
   694→  @Override
   695→  protected void assertAttestationValid(
   696→      final MutableBeaconState state, final Attestation attestation) {
   697→    final Optional<OperationInvalidReason> invalidReason =
   698→        validateAttestation(state, attestation.getData());
   699→    checkArgument(
   700→        invalidReason.isEmpty(),
   701→        "process_attestations: %s",
   702→        invalidReason.map(OperationInvalidReason::describe).orElse(""));
   703→
   704→    final List<UInt64> committeeIndices = attestation.getCommitteeIndicesRequired();
   705→    final UInt64 committeeCountPerSlot =
   706→        beaconStateAccessorsElectra.getCommitteeCountPerSlot(
   707→            state, attestation.getData().getTarget().getEpoch());
   708→    final SszBitlist aggregationBits = attestation.getAggregationBits();
   709→    final Optional<OperationInvalidReason> committeeCheckResult =
   710→        checkCommittees(
   711→            committeeIndices,
   712→            committeeCountPerSlot,
   713→            state,
   714→            attestation.getData().getSlot(),
   715→            aggregationBits);
   716→    if (committeeCheckResult.isPresent()) {
   717→      throw new IllegalArgumentException(committeeCheckResult.get().describe());
   718→    }
   719→  }
   720→
   721→  private Optional<OperationInvalidReason> checkCommittees(
   722→      final List<UInt64> committeeIndices,
   723→      final UInt64 committeeCountPerSlot,
   724→      final BeaconState state,
   725→      final UInt64 slot,
   726→      final SszBitlist aggregationBits) {
   727→    int committeeOffset = 0;
   728→    for (final UInt64 committeeIndex : committeeIndices) {
   729→      if (committeeIndex.isGreaterThanOrEqualTo(committeeCountPerSlot)) {
   730→        return Optional.of(AttestationInvalidReason.COMMITTEE_INDEX_TOO_HIGH);
   731→      }
   732→      final IntList committee =
   733→          beaconStateAccessorsElectra.getBeaconCommittee(state, slot, committeeIndex);
   734→      final int currentCommitteeOffset = committeeOffset;
   735→      final boolean committeeHasAtLeastOneAttester =
   736→          IntStream.range(0, committee.size())
   737→              .anyMatch(
   738→                  committeeParticipantIndex ->
   739→                      aggregationBits.isSet(currentCommitteeOffset + committeeParticipantIndex));
   740→      if (!committeeHasAtLeastOneAttester) {
   741→        return Optional.of(AttestationInvalidReason.PARTICIPANTS_COUNT_MISMATCH);
   742→      }
   743→      committeeOffset += committee.size();
   744→    }
   745→    if (committeeOffset != aggregationBits.size()) {
   746→      return Optional.of(AttestationInvalidReason.PARTICIPANTS_COUNT_MISMATCH);
   747→    }
   748→    return Optional.empty();
   749→  }
   750→}
   751→

